mod io;
use quantum_ecc::circuit::{Op,OperationType as K,QubitId,BitId};
use std::collections::{HashMap,HashSet,BTreeSet};
use sha3::{Digest,Sha3_256};
type E=u32;
// Exact semantic keys for small classical Boolean supports. Large functions
// remain opaque symbols of their actual immutable expressions; no sampling.
#[derive(Clone,Debug,PartialEq,Eq,Hash)]struct SemTruth{atoms:Vec<u32>,table:u64}
impl SemTruth{
 fn mask(n:usize)->u64{if n==6{u64::MAX}else{(1u64<<(1usize<<n))-1}}
 fn complement(&self)->Self{Self{atoms:self.atoms.clone(),table:self.table^Self::mask(self.atoms.len())}}
 fn shrink(mut self)->Self{let mut bit=0;while bit<self.atoms.len(){let n=self.atoms.len();let step=1usize<<bit;let independent=(0..1usize<<n).filter(|r|r&step==0).all(|r|(self.table>>r)&1==(self.table>>(r|step))&1);if independent{let mut out=0u64;for row in 0..1usize<<(n-1){let old=(row&(step-1))|((row&!(step-1))<<1);out|=((self.table>>old)&1)<<row;}self.atoms.remove(bit);self.table=out;}else{bit+=1;}}self}
 fn key(&self)->(Self,u32){let neg=(self.table&1)as u32;if neg==0{(self.clone(),0)}else{(self.complement(),1)}}
}
impl Expr{
 fn semantic(&self,v:u32)->SemTruth{if v<=1{return SemTruth{atoms:vec![],table:v as u64};}let t=&self.truths[(v/2-1)as usize];if v&1==0{t.clone()}else{t.complement()}}
 fn combine_semantic(&self,k:u8,a:u32,b:u32)->Option<SemTruth>{let a=self.semantic(a);let b=self.semantic(b);let mut atoms=a.atoms.clone();atoms.extend_from_slice(&b.atoms);atoms.sort_unstable();atoms.dedup();if atoms.len()>6{return None;}let ap:Vec<_>=a.atoms.iter().map(|v|atoms.binary_search(v).unwrap()).collect();let bp:Vec<_>=b.atoms.iter().map(|v|atoms.binary_search(v).unwrap()).collect();let project=|row:usize,positions:&[usize]|positions.iter().enumerate().fold(0usize,|v,(i,&bit)|v|(((row>>bit)&1)<<i));let mut table=0;for row in 0..1usize<<atoms.len(){let av=(a.table>>project(row,&ap))&1;let bv=(b.table>>project(row,&bp))&1;table|=(if k==1{av&bv}else{av^bv})<<row;}Some(SemTruth{atoms,table}.shrink())}
 fn semantic_node(&mut self,k:u8,a:u32,b:u32)->u32{let summary=self.combine_semantic(k,a,b);if let Some(t)=&summary{if t.atoms.is_empty(){return(t.table&1)as u32;}let(key,neg)=t.key();if let Some(&v)=self.canonical.get(&key){return v^neg;}}let id=self.atom();*self.nodes.last_mut().unwrap()=(k,a,b);if let Some(t)=summary{let(key,neg)=t.key();*self.truths.last_mut().unwrap()=t;self.canonical.insert(key,id^neg);}id}
}

#[derive(Default)]struct Expr{restricting:bool,truths:Vec<SemTruth>,canonical:HashMap<SemTruth,u32>,nodes:Vec<(u8,u32,u32)>,implications:HashMap<(u32,u32),bool>,next:u32,and:HashMap<(u32,u32),u32>,xor:HashMap<(u32,u32),u32>}
impl Expr{
 fn atom(&mut self)->u32{self.next+=2;self.nodes.push((0,0,0));let t=SemTruth{atoms:vec![self.next],table:2};self.truths.push(t.clone());self.canonical.insert(t,self.next);self.next}
 fn and(&mut self,mut a:u32,mut b:u32)->u32{if a==0||b==0{return 0;}if a==1{return b;}if b==1||a==b{return a;}if a==b^1{return 0;}if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&v)=self.and.get(&(a,b)){return v;}if !self.restricting{self.restricting=true;let mut result=None;if let Some(v)=self.cofactor(b,a,6){if v!=b{result=Some(self.and(a,v));}}if result.is_none(){if let Some(v)=self.cofactor(a,b,6){if v!=a{result=Some(self.and(b,v));}}}self.restricting=false;if let Some(v)=result{self.and.insert((a,b),v);return v;}}let v=self.semantic_node(1,a,b);self.and.insert((a,b),v);v}
 fn or(&mut self,a:u32,b:u32)->u32{self.and(a^1,b^1)^1}
 fn xor(&mut self,mut a:u32,mut b:u32)->u32{if a==0{return b;}if b==0{return a;}if a==1{return b^1;}if b==1{return a^1;}if a==b{return 0;}if a==b^1{return 1;}let neg=(a^b)&1;a&=!1;b&=!1;if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&v)=self.xor.get(&(a,b)){return v^neg;}let v=self.semantic_node(2,a,b);self.xor.insert((a,b),v);v^neg}
 fn ite(&mut self,g:u32,new:u32,old:u32)->u32{if g==0||new==old{return old;}if g==1{return new;}if old==0{return self.and(g,new);}if new==0{return self.and(g^1,old);}if old==1{return self.or(g^1,new);}if new==1{return self.or(g,old);}if new==old^1{return self.xor(g,old);}let a=self.and(g,new);let b=self.and(g^1,old);self.or(a,b)}
}
impl Expr{
 fn quick_implies(&self,a:u32,b:u32,depth:usize)->bool{if a==0||b==1||a==b{return true;}if depth==0||a<=1||b==0{return false;}let an=self.nodes[(a/2-1)as usize];if an.0==1{if a&1==0{if self.quick_implies(an.1,b,depth-1)||self.quick_implies(an.2,b,depth-1){return true;}}else if self.quick_implies(an.1^1,b,depth-1)&&self.quick_implies(an.2^1,b,depth-1){return true;}}let bn=self.nodes[(b/2-1)as usize];if bn.0==1{if b&1==0{return self.quick_implies(a,bn.1,depth-1)&&self.quick_implies(a,bn.2,depth-1);}return self.quick_implies(a,bn.1^1,depth-1)||self.quick_implies(a,bn.2^1,depth-1);}false}
 fn implies(&mut self,a:u32,b:u32)->bool{if self.quick_implies(a,b,12){return true;}if let Some(&v)=self.implications.get(&(a,b)){return v;}let root=self.and(a,b^1);let answer=self.zero_truth_table(root);self.implications.insert((a,b),answer);answer}
 fn zero_truth_table(&self,root:u32)->bool{if root<=1{return root==0;}let mut pending=vec![root&!1];let mut visited=BTreeSet::new();let mut atoms=BTreeSet::new();while let Some(id)=pending.pop(){if id<=1||!visited.insert(id){continue;}if visited.len()>4096{return false;}let(k,a,b)=self.nodes[(id/2-1)as usize];if k==0{atoms.insert(id);if atoms.len()>10{return false;}}else{pending.push(a&!1);pending.push(b&!1);}}
  let ord:HashMap<_,_>=atoms.into_iter().enumerate().map(|(i,v)|(v,i)).collect();let cases=1usize<<ord.len();let words=cases.div_ceil(64);let mut table:HashMap<u32,Vec<u64>>=HashMap::new();let get=|lit:u32,table:&HashMap<u32,Vec<u64>>,j:usize|if lit<=1{if lit==1{u64::MAX}else{0}}else{let v=table[&(lit&!1)][j];if lit&1!=0{!v}else{v}};
  for id in visited{let(k,a,b)=self.nodes[(id/2-1)as usize];let mut row=vec![0;words];if k==0{let shift=ord[&id];for assignment in 0..cases{row[assignment/64]|=(((assignment>>shift)&1)as u64)<<(assignment%64);}}else{for j in 0..words{let x=get(a,&table,j);let y=get(b,&table,j);row[j]=if k==1{x&y}else{x^y};}}table.insert(id,row);}
  let last_mask=if cases<64{(1u64<<cases)-1}else{u64::MAX};(0..words).all(|j|get(root,&table,j)&if j+1==words{last_mask}else{u64::MAX}==0)
 }
}
impl Expr{fn cofactor(&mut self,expression:u32,assumed:u32,depth:usize)->Option<u32>{if expression==assumed{return Some(1);}if expression==assumed^1{return Some(0);}if expression<=1||depth==0{return None;}let(k,a,b)=self.nodes[(expression/2-1)as usize];if k==0{return None;}let left=self.cofactor(a,assumed,depth-1);let right=self.cofactor(b,assumed,depth-1);if left.is_none()&&right.is_none(){return None;}let a=left.unwrap_or(a);let b=right.unwrap_or(b);let value=if k==1{self.and(a,b)}else{self.xor(a,b)};Some(value^(expression&1))}}

struct Algebra{inner:Expr}
impl Algebra{fn fresh(&mut self)->E{self.inner.atom()}fn and(&mut self,a:&E,b:&E)->E{self.inner.and(*a,*b)}fn xor(&mut self,a:&E,b:&E)->E{self.inner.xor(*a,*b)}fn select(&mut self,old:&E,new:&E,cond:&E)->E{self.inner.ite(*cond,*new,*old)}}
fn initial_inputs(ops:&[Op],nq:usize,nb:usize,alg:&mut Algebra)->(Vec<E>,Vec<E>){let no=u64::MAX;let(mut q,mut c)=(vec![0;nq],vec![0;nb]);let(mut qs,mut cs)=(HashSet::new(),HashSet::new());for o in ops{if o.kind==K::AppendToRegister{if o.q_target.0!=no&&qs.insert(o.q_target.0){q[o.q_target.0 as usize]=alg.fresh();}if o.c_target.0!=no&&cs.insert(o.c_target.0){c[o.c_target.0 as usize]=alg.fresh();}}}(q,c)}
fn hash(ops:&[Op])->String {
 let mut h=Sha3_256::new();for o in ops {h.update((o.kind as u64).to_le_bytes());
 for v in [o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{h.update(v.to_le_bytes());}}
 format!("{:x}",h.finalize())
}
fn make(k:K,c2:u64,c1:u64,t:u64,ct:u64,cc:u64)->Op {
 let mut o=Op::empty();o.kind=k;o.q_control2=QubitId(c2);o.q_control1=QubitId(c1);o.q_target=QubitId(t);o.c_target=BitId(ct);o.c_condition=BitId(cc);o.validate();o
}
#[derive(Clone,Copy,Debug)]struct Recipe{wire:usize,a:usize,b:usize,kind:K,guard:u32,producer:usize}
struct PeakRegion{max_need:usize,lo:usize,candidates:Vec<Recipe>,touches:HashSet<usize>,writes:HashSet<usize>}
fn peak_audit(ops:&[Op])->serde_json::Value{let nq=quantum_ecc::circuit::analyze_ops(ops.iter()).0 as usize;peak_audit_cap(ops,nq-1)}
fn peak_audit_cap(ops:&[Op],cap:usize)->serde_json::Value{
 let no=u64::MAX;let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq,nb)=(nq as usize,nb as usize);assert!(cap<nq);let mut alg=Algebra{inner:Expr::default()};let(mut q,mut c)=initial_inputs(ops,nq,nb,&mut alg);let pinned:HashSet<_>=ops.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=no).map(|o|o.q_target.0 as usize).collect();let mut active:Vec<bool>=(0..nq).map(|j|pinned.contains(&j)).collect();let mut live=pinned.len();let mut recipes=vec![None;nq];let(mut base,mut stack)=(1,vec![]);let mut pending:Option<PeakRegion>=None;let mut rows=vec![];let mut ccx_loans=0usize;let mut free_loans=0usize;let mut failed=0usize;let mut original_peak=live;
 for(i,o)in ops.iter().enumerate(){
  if o.kind==K::PushCondition{stack.push(base);base=alg.inner.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}
  let g=if o.c_condition.0==no{base}else{alg.inner.and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);let mut used:Vec<_>=[o.q_control2.0,o.q_control1.0,o.q_target.0].into_iter().filter(|&j|j!=no).map(|j|j as usize).collect();used.sort_unstable();used.dedup();
  let new_count=used.iter().filter(|&&j|!active[j]).count();let need=live+new_count;original_peak=original_peak.max(need);
  if need>cap&&pending.is_none(){assert!(need<=nq);let mut candidates=vec![];for wire in 0..nq{if pinned.contains(&wire)||!active[wire]||q[wire]==0{continue;}let Some(recipe)=recipes[wire]else{continue;};let r:Recipe=recipe;let actual=match r.kind{K::X=>r.guard,K::CX=>alg.inner.and(r.guard,q[r.a]),K::CCX=>{let ab=alg.inner.and(q[r.a],q[r.b]);alg.inner.and(r.guard,ab)},_=>unreachable!()};if actual==q[wire]{candidates.push(r);}}
   pending=Some(PeakRegion{max_need:need,lo:i,candidates,touches:HashSet::new(),writes:HashSet::new()});
  }
  for &j in &used{if !active[j]{active[j]=true;live+=1;}}
  let mut affected=vec![];if matches!(o.kind,K::X|K::CX|K::CCX|K::Swap|K::R|K::Hmr){affected.push(t);if o.kind==K::Swap{affected.push(a);}}
  if let Some(region)=&mut pending{region.max_need=region.max_need.max(need);region.touches.extend(used.iter().copied());region.writes.extend(affected.iter().copied());}
  let recipe=if matches!(o.kind,K::X|K::CX|K::CCX)&&q[t]==0{Some(Recipe{wire:t,a,b,kind:o.kind,guard:g,producer:i})}else{None};for &j in &affected{recipes[j]=None;}
  match o.kind{K::X=>q[t]=alg.inner.xor(q[t],g),K::CX=>{let v=alg.inner.and(q[a],g);q[t]=alg.inner.xor(q[t],v);},K::CCX=>{let v=alg.inner.and(q[a],q[b]);let v=alg.inner.and(g,v);q[t]=alg.inner.xor(q[t],v);},K::Swap=>{let v=alg.inner.xor(q[a],q[t]);let v=alg.inner.and(g,v);q[a]=alg.inner.xor(q[a],v);q[t]=alg.inner.xor(q[t],v);},K::R|K::Hmr=>{q[t]=alg.inner.and(q[t],g^1);if o.kind==K::Hmr{let r=alg.inner.atom();c[ct]=alg.inner.ite(g,r,c[ct]);}},K::BitInvert=>c[ct]=alg.inner.xor(c[ct],g),K::BitStore0=>c[ct]=alg.inner.and(c[ct],g^1),K::BitStore1=>c[ct]=alg.inner.or(c[ct],g),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
  if let Some(recipe)=recipe{recipes[t]=Some(recipe);}
  for &j in &used{if !pinned.contains(&j)&&q[j]==0{assert!(active[j]);active[j]=false;live-=1;}}
  if live<=cap{if let Some(region)=pending.take(){let mut good:Vec<_>=region.candidates.iter().copied().filter(|r|{if region.touches.contains(&r.wire){return false;}let restored=match r.kind{K::X=>r.guard,K::CX=>alg.inner.and(r.guard,q[r.a]),K::CCX=>{let ab=alg.inner.and(q[r.a],q[r.b]);alg.inner.and(r.guard,ab)},_=>unreachable!()};restored==q[r.wire]}).collect();good.sort_by_key(|r|(u32::from(r.kind==K::CCX),u32::from(r.kind==K::CX),r.wire));let count=good.len();let needed=region.max_need-cap;let mut selected:Vec<Recipe>=vec![];for r in good{let controls=|r:&Recipe|{let mut v=vec![];if r.kind!=K::X{v.push(r.a);}if r.kind==K::CCX{v.push(r.b);}v};if selected.iter().all(|old|!controls(old).contains(&r.wire)&&!controls(&r).contains(&old.wire)){selected.push(r);if selected.len()==needed{break;}}}
   if selected.len()==needed{let r=selected[0];let ccx=selected.iter().filter(|r|r.kind==K::CCX).count();ccx_loans+=ccx;free_loans+=selected.len()-ccx;let victims:Vec<_>=selected.iter().map(|r|serde_json::json!({"wire":r.wire,"a":r.a,"b":r.b,"kind":r.kind as u32,"producer":r.producer,"captured_guard_expression":r.guard})).collect();rows.push(serde_json::json!({"lo":region.lo,"hi":i,"status":"EXACT_IDLE_VICTIM_SET_AND_RESTORABLE_PRODUCTS_PROVED","candidates":count,"needed":needed,"wire":r.wire,"a":r.a,"b":r.b,"kind":r.kind as u32,"producer":r.producer,"captured_guard_expression":r.guard,"victims":victims,"extra_toffoli_records_upper_bound":2*ccx}));}
   else{failed+=1;rows.push(serde_json::json!({"lo":region.lo,"hi":i,"status":"NO_SUFFICIENT_INDEPENDENT_RESTORABLE_VICTIM_SET","needed":needed,"independent_available":selected.len(),"surviving_exact_recipe_candidates":count,"initial_recipe_candidates":region.candidates.len(),"touched_quantum_wires":region.touches.len(),"written_quantum_wires":region.writes.len()}));}}}

  if i%1000000==0{eprintln!("PEAK_REMAT op={i} regions={} free_loans={free_loans} ccx_loans={ccx_loans} failed={failed} nodes={}",rows.len(),alg.inner.nodes.len());}
 }
 assert!(stack.is_empty());let incomplete=pending.is_some();serde_json::json!({"status":"READ_ONLY_PEAK_REMATERIALIZATION_PLAN_NOT_AN_EMITTED_CIRCUIT_OR_SCORE","original_qubits":nq,"target_cap":cap,"conservative_original_lifetime_peak":original_peak,"regions":rows,"zero_toffoli_recipe_regions":free_loans,"two_toffoli_recipe_regions":ccx_loans,"unproved_regions":failed,"unfinished_final_region":incomplete,"all_regions_covered":failed==0&&!incomplete,"extra_executed_toffoli_per_shot_upper_bound":if failed==0&&!incomplete{Some(2*ccx_loans)}else{None},"semantic_nodes":alg.inner.nodes.len(),"input_records_sha3":hash(ops),"scope":"Each selected helper is a proved X/CX/CCX of original historical classical guard and CURRENT controls; helper untouched and its full captured-guard product exactly restored at region end; control writes allowed only under that equality proof. Uncompute before region and restore after a physical slot frees. Historical guard must be captured at original producer, both inserted gates outside original scope stack via exact guard flattening. No inserted RNG. This is a source-bound plan, NOT achieved Q/T; actual allocator/guard emitter/native full phase/RNG qualification and final pipeline required."})
}
#[cfg(test)]mod peak_remat_tests{use super::*;
 fn fixture(kind:K)->Vec<Op>{let n=u64::MAX;let mut ops=vec![];for q in 0..4{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(0);o.q_target=QubitId(q);ops.push(o);}let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(1);o.c_target=BitId(0);ops.push(o);ops.extend([make(kind,if kind==K::CCX{1}else{n},0,4,n,0),make(K::CX,n,1,5,n,n),make(K::R,n,n,5,n,n),make(K::CX,n,4,2,n,n),make(K::R,n,n,4,n,n)]);ops}
 #[test]fn peak_island_has_exact_idle_clifford_or_toffoli_recipe(){for kind in[K::CX,K::CCX]{let s=peak_audit(&fixture(kind));assert_eq!(s["target_cap"],5);assert_eq!(s["conservative_original_lifetime_peak"],6);assert_eq!(s["all_regions_covered"],true);assert_eq!(s["extra_executed_toffoli_per_shot_upper_bound"],if kind==K::CX{0}else{2});}}
 #[test]fn uncompute_restore_preserves_full_phase_values_rng_and_captured_old_classical_guard(){use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;struct W{word:u64,at:usize}impl XofReader for W{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.word.rotate_left(self.at as u32).to_le_bytes());self.at+=1;}}let n=u64::MAX;for kind in[K::CX,K::CCX]{let mut ops=fixture(kind);ops.insert(7,make(K::BitInvert,n,n,n,0,n));let plan=peak_audit(&ops);assert_eq!(plan["all_regions_covered"],true);let r=&plan["regions"][0];let(lo,hi)=(r["lo"].as_u64().unwrap()as usize,r["hi"].as_u64().unwrap()as usize);let producer=r["producer"].as_u64().unwrap()as usize;let mut out=vec![];let mut inserted=ops[producer];inserted.c_condition=BitId(1);for(i,&o)in ops.iter().enumerate(){if i==producer{out.push(make(K::BitStore0,n,n,n,1,n));out.push(make(K::BitStore1,n,n,n,1,0));}if i==lo{out.push(inserted);}out.push(o);if i==hi{out.push(inserted);}}for word in[0,u64::MAX,0xa55a_dd33_ff00_1701]{let(mut ra,mut rb)=(W{word,at:0},W{word,at:0});let(mut a,mut b)=(Simulator::new(6,2,&mut ra),Simulator::new(6,2,&mut rb));for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}a.bits[0]|=((lane>>4&1)as u64)<<lane;}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);let guard=a.bits[0];a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits[0],b.bits[0]);assert_eq!(a.phase,b.phase);assert_eq!(b.stats.toffoli_gates-a.stats.toffoli_gates,if kind==K::CCX{2*guard.count_ones()as u64}else{0});drop((a,b));assert_eq!(ra.at,rb.at);}}}
}
#[cfg(test)]mod semantic_algebra_controls{use super::*;
 #[test]fn distributivity_and_unused_support_are_exact(){let mut e=Expr::default();let a=e.atom();let b=e.atom();let ab=e.and(a,b);let anb=e.and(a,b^1);assert_eq!(e.xor(ab,anb),a);let or=e.or(a,b);assert_eq!(e.and(or,a),a);assert_ne!(or,a);}
 #[test]fn above_six_atom_cofactor_has_disabled_negative_control(){fn run(enabled:bool)->(u32,u32){let mut e=Expr::default();e.restricting=!enabled;let mut g=1;let mut old=1;for _ in 0..6{let a=e.atom();g=e.and(g,a);let b=e.atom();old=e.and(old,b);}assert_eq!(e.semantic(g).atoms.len(),6);assert_eq!(e.semantic(old).atoms.len(),6);let r=e.atom();let v=e.ite(g,r,old);let actual=e.and(g,v);let expected=e.and(g,r);(actual,expected)}let no=run(false);assert_ne!(no.0,no.1);let yes=run(true);assert_eq!(yes.0,yes.1);}
 #[test]fn complete_six_atom_expression_truths_match_original_functions(){fn get(e:&Expr,v:u32,assignment:usize,atoms:&[u32])->bool{if v<=1{return v==1;}let(k,a,b)=e.nodes[(v/2-1)as usize];let value=match k{0=>assignment>>atoms.iter().position(|&a|a==v&!1).unwrap()&1!=0,1=>get(e,a,assignment,atoms)&get(e,b,assignment,atoms),_=>get(e,a,assignment,atoms)^get(e,b,assignment,atoms)};value^(v&1!=0)}let mut e=Expr::default();let atoms:Vec<_>=(0..6).map(|_|e.atom()).collect();let mut pool=atoms.clone();let mut seed=0xa8d7135f23649b01u64;for _ in 0..500{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let(a,b,g)=(pool[seed as usize%pool.len()],pool[(seed>>17)as usize%pool.len()],pool[(seed>>33)as usize%pool.len()]);let kind=seed%3;let v=match kind{0=>e.and(a,b),1=>e.xor(a,b),_=>e.ite(g,a,b)};for assignment in 0..64{let(a,b,g)=(get(&e,a,assignment,&atoms),get(&e,b,assignment,&atoms),get(&e,g,assignment,&atoms));let want=match kind{0=>a&b,1=>a^b,_=>if g{a}else{b}};assert_eq!(get(&e,v,assignment,&atoms),want);}pool.push(v);if pool.len()>64{pool.remove(6);}}}
}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),4);let ops=io::load_ops(&a[1]);let cap=a[3].parse().unwrap();let r=peak_audit_cap(&ops,cap);std::fs::write(format!("{}.json",a[2]),serde_json::to_string_pretty(&r).unwrap()+"\n").unwrap();println!("SUMMARY cap={} covered={} regions={} zeroT={} twoT={} unproved={} extraT={}",cap,r["all_regions_covered"],r["regions"].as_array().unwrap().len(),r["zero_toffoli_recipe_regions"],r["two_toffoli_recipe_regions"],r["unproved_regions"],r["extra_executed_toffoli_per_shot_upper_bound"]);}


#[cfg(test)]mod multicap_tests{use super::*;
 fn meta()->Vec<Op>{(0..4).map(|q|{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(0);o.q_target=QubitId(q);o}).collect()}
 #[test]fn two_simultaneous_victims_cover_a_two_qubit_peak_without_dependency_cycle(){let n=u64::MAX;let mut ops=meta();ops.extend([make(K::CCX,0,1,4,n,n),make(K::CX,n,2,5,n,n),make(K::CX,n,0,6,n,n),make(K::CX,n,1,7,n,n),make(K::R,n,n,6,n,n),make(K::R,n,n,7,n,n),make(K::CX,n,4,2,n,n),make(K::CX,n,5,3,n,n),make(K::R,n,n,4,n,n),make(K::R,n,n,5,n,n)]);let s=peak_audit_cap(&ops,6);assert_eq!(s["all_regions_covered"],true);assert_eq!(s["regions"][0]["needed"],2);assert_eq!(s["regions"][0]["victims"].as_array().unwrap().len(),2);assert_eq!(s["extra_executed_toffoli_per_shot_upper_bound"],2);}
 #[test]fn modified_controls_are_allowed_only_if_the_original_product_is_exactly_restored(){let n=u64::MAX;let mut ops=meta();ops.extend([make(K::CCX,0,1,4,n,n),make(K::CX,n,2,5,n,n),make(K::CX,n,0,1,n,n),make(K::X,n,n,1,n,n),make(K::R,n,n,5,n,n),make(K::CX,n,4,2,n,n),make(K::R,n,n,4,n,n)]);let s=peak_audit_cap(&ops,5);assert_eq!(s["all_regions_covered"],true);ops[7]=make(K::Z,n,n,1,n,n);let s=peak_audit_cap(&ops,5);assert_eq!(s["all_regions_covered"],false);assert!(s["extra_executed_toffoli_per_shot_upper_bound"].is_null());}
}
